import {Engine} from './engine.js';
const $=id=>document.getElementById(id);
const canvas=$('game'),overlay=$('overlay'),dialog=$('controlsDialog');
let game,started=false,toastTimer,wasPaused=false,last=0,accumulator=0;
const roomNames={room26:'Home',rMenu:'Original menu',introroom2:'The story begins',introroom:'A new day',room1:'Into the world',room3:'The adventure continues',rEnding:'The end',petrolstationroom:'Petrol station'};
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2200);}
function clearInput(){if(!game)return;for(const k of game.input.keys)game.input.released.add(k);game.input.keys.clear();game.input.buttons.clear();game.input.bpressed.clear();game.input.pressed.clear();}
function paused(value){if(!started)return;game.paused=value;clearInput();overlay.hidden=!value;$('panelKicker').textContent='TAKE A BREATHER';$('panelTitle').textContent='Adventure can wait.';$('panelDescription').textContent='Your world is right where you left it.';$('playLabel').textContent='Resume game';$('continueButton').hidden=true;$('startHint').textContent='Press Escape to resume';$('pauseLabel').textContent=value?'Resume':'Pause';$('playerStatus').textContent=value?'PAUSED':'PLAYING';$('statusDot').classList.toggle('paused',value);if(value)game.audioStop();else{resumeAmbience();canvas.focus();}last=0;accumulator=0;}
function resumeAmbience(){if(game.audioEnabled&&['room26','petrolstationroom'].includes(game.room.info.Name))game.audioPlay(game.assets.nightsounds,true);}
function start(restore=false){if(started){paused(false);return;}started=true;game.paused=false;game.audioEnabled=!$('soundButton').classList.contains('muted');if(restore&&!game.restoreCheckpoint())toast('No saved adventure yet.');overlay.hidden=true;for(const id of ['pauseButton','saveButton','menuButton'])$(id).disabled=false;$('playerStatus').textContent='PLAYING';resumeAmbience();canvas.focus();last=0;}
function frame(time){requestAnimationFrame(frame);if(!game)return;if(!last)last=time;const dt=Math.min(100,time-last);last=time;if(started&&!game.paused){accumulator+=dt;const step=1000/game.fps;let n=0;while(accumulator>=step&&n++<5){game.step();accumulator-=step;}}else accumulator=0;game.renderer.draw();}
$('playButton').onclick=()=>start();$('continueButton').onclick=()=>start(true);
$('pauseButton').onclick=()=>paused(!game.paused);
$('saveButton').onclick=()=>{if(game.saveCheckpoint()){toast('Adventure saved');}else toast('Save when Daniel is in the world.');canvas.focus();};
$('menuButton').onclick=()=>{game.saveCheckpoint();game.loadRoom(game.assets.rMenu);paused(false);canvas.focus();};
$('soundButton').onclick=()=>{const muted=$('soundButton').classList.toggle('muted');$('soundButton').setAttribute('aria-pressed',String(muted));$('soundButton').setAttribute('aria-label',muted?'Unmute sound':'Mute sound');$('soundButton').title=muted?'Unmute sound':'Mute sound';document.querySelector('.sound-waves').style.opacity=muted?'0.15':'1';if(game){game.audioEnabled=!muted;if(muted)game.audioStop();else if(started&&!game.paused)resumeAmbience();}canvas.focus();};
$('fullscreenButton').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.game-frame').requestFullscreen();canvas.focus();}catch{toast('Fullscreen is unavailable in this browser.');}};
$('controlsButton').onclick=()=>{wasPaused=game?.paused??true;if(started)paused(true);dialog.showModal();};dialog.addEventListener('close',()=>{if(started&&!wasPaused)paused(false);});
const alias={37:65,39:68,38:87};
function key(n,down){for(const k of [n,...(alias[n]?[alias[n]]:[])]){if(down){if(!game.input.keys.has(k))game.input.pressed.add(k);game.input.keys.add(k);}else{game.input.keys.delete(k);game.input.released.add(k);}}}
document.addEventListener('keydown',e=>{if(!game||dialog.open)return;if(e.key==='Escape'){e.preventDefault();if(started)paused(!game.paused);return;}if(!started){if(e.key==='Enter'||e.code==='Space'){e.preventDefault();start();}return;}if(game.paused)return;if(['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','KeyA','KeyD','KeyW','KeyF','KeyS','KeyL','KeyE','KeyQ','KeyR','Enter'].includes(e.code))e.preventDefault();key(e.keyCode,true);});
document.addEventListener('keyup',e=>{if(game)key(e.keyCode,false);});
canvas.addEventListener('pointermove',e=>{if(!game)return;const b=canvas.getBoundingClientRect();game.input.mx=(e.clientX-b.left)/b.width;game.input.my=(e.clientY-b.top)/b.height;});
canvas.addEventListener('pointerdown',e=>{if(!game||game.paused||!started)return;canvas.focus();canvas.setPointerCapture(e.pointerId);const b=canvas.getBoundingClientRect();game.input.mx=(e.clientX-b.left)/b.width;game.input.my=(e.clientY-b.top)/b.height;const n=e.button===2?2:e.button===1?3:1;game.input.buttons.add(n);game.input.bpressed.add(n);e.preventDefault();});
canvas.addEventListener('pointerup',e=>{if(!game)return;const n=e.button===2?2:e.button===1?3:1;game.input.buttons.delete(n);game.input.breleased.add(n);});canvas.addEventListener('contextmenu',e=>e.preventDefault());
window.addEventListener('blur',()=>{if(started&&!game.paused)paused(true);clearInput();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&started&&!game.paused)paused(true);});
for(const button of document.querySelectorAll('.touch-controls button')){const change=down=>{if(!game||!started)return;if(button.dataset.key)key(Number(button.dataset.key),down);else{const n=Number(button.dataset.mouse);if(down){game.input.buttons.add(n);game.input.bpressed.add(n);}else{game.input.buttons.delete(n);game.input.breleased.add(n);}}button.classList.toggle('active',down);};button.addEventListener('pointerdown',e=>{button.setPointerCapture(e.pointerId);change(true);e.preventDefault();});button.addEventListener('pointerup',()=>change(false));button.addEventListener('pointercancel',()=>change(false));}
async function init(){try{const response=await fetch('data.json');if(!response.ok)throw new Error('Game data could not load');game=new Engine(await response.json(),canvas);game.audioEnabled=false;await game.renderer.load();game.loadRoom(game.assets.room26,false);for(let i=0;i<2;i++)game.step();game.paused=true;game.onRoomChange=name=>$('location').textContent=roomNames[name]||'Exploring';game.onSave=()=>toast('Adventure saved');game.onExit=()=>paused(true);$('playButton').disabled=false;$('playLabel').textContent='Play the game';$('continueButton').hidden=!game.readFile('checkpoint');window.himr=game;requestAnimationFrame(frame);}catch(error){console.error(error);$('panelTitle').textContent='The adventure is loading.';$('panelDescription').textContent='Reload the page to try again.';$('playLabel').textContent='Unable to load';}}
init();
